@CrossOrigin
@RestController
@RequestMapping("/DocumentQuery")
public class DocumentQueryRestController extends BaseSpringRestController {
	
	public DocumentQueryRestController( DocumentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Document using a UUID
     * @param		UUID documentId
     * @return		Document
     */    
    @GetMapping("/load")
    public Document load( @RequestParam(required=true) UUID documentId ) {
    	Document entity = null;

    	try {  
    		entity = service.getDocument( new DocumentFetchOneSummary( documentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Document using Id " + documentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Document business objects
     * @return		Set<Document>
     */
    @GetMapping("/")
    public List<Document> loadAll() {                
    	List<Document> documentList = null;
        
    	try {
            // load the Document
            documentList = service.getAllDocument();
            
            if ( documentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Documents" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Documents ", exc );
        	return null;
        }

        return documentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Document document = null;
    protected DocumentService service = null;
    private static final Logger LOGGER = Logger.getLogger(DocumentQueryRestController.class.getName());
    
}
